public:
    long long countInterestingSubarrays(vector<int>& nums, int modulo, int k) {
        unordered_map<int, int> counts;
        counts[0] = 1;
        int curr = 0;
        long long ans = 0;
        for (int x : nums) {
            if (x % modulo == k) {
                curr = (curr + 1) % modulo;
            }
            int target = (curr - k + modulo) % modulo;
