class Solution {
    public long countInterestingSubarrays(List<Integer> nums, int modulo, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        counts.put(0, 1);
        int curr = 0;
        long ans = 0;
        for (int x : nums) {
            if (x % modulo == k) {
                curr = (curr + 1) % modulo;
            }
            int target = (curr - k + modulo) % modulo;
            ans += counts.getOrDefault(target, 0);
            counts.put(curr, counts.getOrDefault(curr, 0) + 1);
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} modulo
 * @param {number} k
 * @return {number}
 */
var countInterestingSubarrays = function(nums, modulo, k) {
    const counts = new Map();
    counts.set(0, 1);
    let curr = 0;
    let ans = 0;
    for (const x of nums) {
        if (x % modulo === k) {
            curr = (curr + 1) % modulo;
        }
        const target = (curr - k + modulo) % modulo;
        ans += counts.get(target) || 0;
        counts.set(curr, (counts.get(curr) || 0) + 1);
    }
    return ans;
};
